# -*- coding: utf-8 -*-
"""Module 15: He thong cabin va he thong thong tin tau bay. KHONG co slide cua giang vien: dung tu Tooley Ch.19 (tr.307-316) va Ch.20 (tr.317-335). Tooley Ch.12 (ESD) gan vao Module 09.
Cac phep tinh bang build/numlib/cabin.py (doi chieu o build/verify/verify_m15.py)."""
import sys, os
sys.path.insert(0, os.path.join(os.path.dirname(__file__), '..', 'numlib'))
from mk import *
import cabin as C

def module(lang):
    pa_vi = table(['Mức', 'Nguồn thông báo'], [['1', 'buồng lái'], ['2', 'bảng tiếp viên phía trước (FAP)'], ['3', 'bảng tiếp viên phía sau hoặc khác'], ['4', 'thông báo ghi sẵn'], ['5', 'nhạc lên máy bay và IFE']])
    pa_en = table(['Level', 'Source of the announcement'], [['1', 'flight deck'], ['2', 'forward attendant panel (FAP)'], ['3', 'rear or other attendant panels'], ['4', 'pre-recorded announcements'], ['5', 'boarding music and IFE']])
    ch_vi = table(['Tín hiệu', 'Âm', 'Gửi từ, tới'], [['Chuông gọi của hành khách', 'một âm cao', 'ghế và nhà vệ sinh tới tiếp viên'], ['Chuông gọi tiếp viên', 'cao/thấp', 'trạm tiếp viên tới trạm tiếp viên khác'], ['Chuông khẩn cấp', 'cao/thấp lặp ba lần', 'tổ lái tới tiếp viên'], ['Biển dây an toàn sáng', 'một âm thấp', 'báo biển dây an toàn đã sáng']])
    ch_en = table(['Signal', 'Tone', 'Sent from, to'], [['Passenger call', 'a single high tone', 'seats and toilets to the cabin crew'], ['Attendant call', 'high/low', 'a crew station to other crew stations'], ['Attendant emergency call', 'high/low repeated three times', 'flight crew to cabin crew'], ['Seat belt sign illuminated', 'a single low tone', 'tells that the seat belt sign is on']])
    parts = [
     (('Hệ thống cabin gom giải trí, thông báo, môi trường và truyền thông lên một máy chủ mạng để giảm cáp và khối lượng', 'Cabin systems put entertainment, announcements, environment and communications on one network server to cut cabling and weight'),
      [('Chức năng cabin và nhu cầu tích hợp', 'Cabin functions and the need for integration'), ('Máy chủ mạng cabin (CNSS) và ARINC 628', 'The cabin network server (CNSS) and ARINC 628'), ('Phân hệ IFE: head-end, phân phối, ghế', 'The IFE subsystem: head-end, distribution, seats')], [
       ('Các dịch vụ cabin trước kia là hệ rời rạc nặng cáp, nay được gom vào mạng dùng chung', 'Cabin services used to be separate cable-heavy systems and are now gathered on a shared network',
        '<p>(Tooley 19.1.) Cabin cung cấp: hướng dẫn an toàn, thông báo của tổ lái, giải trí trên chuyến bay (IFE), thông báo hành khách (loa trên trần và IFE), điện thoại, internet, thư điện tử, báo hiệu và gọi, điều khiển môi trường theo vùng, thương mại điện tử. Ở máy bay cũ mỗi dịch vụ có cáp, nguồn, điều khiển và hiển thị riêng, nặng và tốn điện: ví dụ hệ PA có nhiều bộ khuếch đại 60 đến 120 W cấp cho loa trần theo vùng với dây rất dài, và IFE dùng nhiều ổ đĩa cùng cáp tới từng ghế. Chuyển sang hệ <b>mạng</b> giúp tích hợp hệ tương tự và số, cấu hình lại linh hoạt, tăng an toàn, đáp ứng kỳ vọng hành khách, giảm khối lượng và tiết kiệm nhiên liệu.</p>',
        '<p>(Tooley 19.1.) The cabin offers safety briefings, flight-crew announcements, in-flight entertainment (IFE), passenger address (ceiling loudspeakers and IFE), telephone, internet and email, alerting and calling, zone environmental control and e-commerce. On older aircraft each service had its own cabling, power, controls and displays, heavy and power-hungry: for instance a PA system with several 60 to 120 W amplifiers feeding zoned ceiling loudspeakers over very long cables, and IFE with several disk drives and cabling to every seat. Moving to a <b>network</b> system integrates analogue and digital systems, allows flexible reconfiguration, raises safety, meets passenger expectations and reduces weight and fuel.</p>',
        '<p>So với IMA (Module 13): cùng ý tưởng thay nhiều hệ riêng bằng một nền dùng chung nối bằng mạng, nhưng ở cabin các dịch vụ không phải tới hạn về an toàn bay.</p>', '<p>Compare IMA (Module 13): the same idea of replacing many separate systems with one shared platform on a network, but cabin services are not flight-critical.</p>'),
       ('Máy chủ mạng cabin (CNSS) cho âm thanh, video và dữ liệu dùng chung một tài nguyên mạng, theo ARINC 628', 'The cabin network server system (CNSS) lets audio, video and data share one network resource, following ARINC 628',
        '<p>(Tooley 19.2.) Bốn phân hệ điển hình: IFE, điều khiển môi trường cabin, thông báo hành khách (PA) và truyền thông; tài nguyên mạng và xử lý được dùng chung. Bốn loại người dùng: <b>tổ lái</b> (từ buồng lái), <b>tiếp viên</b> (máy tính bảng), <b>hành khách</b> (bộ ghế, thiết bị cá nhân), <b>nhân viên kỹ thuật</b> (laptop khi bảo dưỡng, bộ nạp phương tiện để cập nhật phương tiện và cấu hình). <b>ARINC 628</b> xác định triết lý kiến trúc và hạ tầng chung: máy chủ thương mại (COTS), truyền thông tốc độ cao có dây và không dây; không quy định từng thiết bị nên nhà chế tạo và khai thác rất linh hoạt.</p>',
        '<p>(Tooley 19.2.) Four typical subsystems: IFE, cabin environmental control, passenger address (PA) and communications; network and processing resources are shared. Four kinds of user: the <b>flight crew</b> (from the flight deck), <b>cabin crew</b> (tablets), <b>passengers</b> (seat units, personal devices) and <b>engineering staff</b> (laptops during maintenance, a media loader to update media and configuration data). <b>ARINC 628</b> defines the general architectural philosophy and infrastructure: commercial (COTS) servers and high-speed wired and wireless communication; it specifies no individual equipment, so manufacturers and operators are very flexible.</p>',
        '<p>ARINC 628 là chuẩn cho mạng thông tin cabin; đừng nhầm với ARINC 429 (bus tốc độ thấp), ARINC 629 và ARINC 664/AFDX (Module 05 và 13). Đây chính là câu 2 Chương 19.</p>', '<p>ARINC 628 is the standard for the cabin information network; do not confuse it with ARINC 429 (a low-speed bus), ARINC 629 and ARINC 664/AFDX (Modules 05 and 13). This is exactly Chapter 19 Q2.</p>'),
       ('IFE gồm head-end ở khoang điện tử, phân phối cabin và phân hệ ghế; nạp phương tiện cần liên kết nhanh', 'An IFE has a head-end in the avionics bay, cabin distribution and a seat subsystem; media loading needs a fast link',
        '<p>(Tooley 19.3.) <b>Head-end</b>: bộ điều khiển hệ thống (SC) cùng lưu trữ phương tiện, giao diện tới các hệ khác và bộ dồn kênh/phân phối âm thanh, video. <b>Phân phối cabin</b>: cáp, hộp rẽ gắn tường và trần, bộ phân phối khu vực, chuyển video, âm thanh, dữ liệu tới ghế và màn hình. <b>Ghế</b>: hộp điện tử ghế (SEB) và bộ điều khiển hành khách (PCU). Bảng điều khiển (CP) ở khu tiếp viên, thường gần cửa cabin phía trước bên trái cùng cổng nạp dữ liệu. Điện thoại ghế nối qua mạng IFE tới SC rồi qua SATCOM. Bộ nạp phương tiện nạp vào bộ nhớ lớn của SC: 100 Mbps có thể đủ nhưng ưu tiên Gigabit Ethernet.</p>' + formula('Thời gian nạp tệp', r't=\frac{8\times\text{size}}{\text{rate}}\qquad(4{,}7\text{ GB}:\;t=' + f'{C.load_time(4.7, 100e6):.0f}'.replace('.', ',') + r'\text{ s at }100\text{ Mbit/s},\;' + f'{C.load_time(4.7, 1e9):.1f}'.replace('.', '{,}') + r'\text{ s at }1\text{ Gbit/s})'),
        '<p>(Tooley 19.3.) <b>Head-end</b>: a system controller (SC) with media storage, an interface to other systems and multiplexers/distribution units for audio and video. <b>Cabin distribution</b>: cabling, wall- and ceiling-mounted tapping boxes and area distribution units routing video, audio and data to seats and screens. <b>Seat</b>: a seat electronic box (SEB) and a passenger control unit (PCU). The control panel (CP) is in the cabin crew area, often near the forward left cabin door with the data load ports. In-seat telephones connect through the IFE network to the SC and then via SATCOM. A media loader fills the SC\'s mass memory: 100 Mbps may suffice but Gigabit Ethernet is preferred.</p>' + formula('File loading time', r't=\frac{8\times\text{size}}{\text{rate}}\qquad(4.7\text{ GB}:\;t=' + f'{C.load_time(4.7, 100e6):.0f}' + r'\text{ s at }100\text{ Mbit/s},\;' + f'{C.load_time(4.7, 1e9):.1f}' + r'\text{ s at }1\text{ Gbit/s})'),
        '<p>Kích thước 4,7 GB và quy ước 1 GB = 10⁹ byte là giả định của site để minh hoạ, không phải số của sách; phép tính bỏ qua mào đầu giao thức.</p>', '<p>The 4.7 GB size and the 1 GB = 10⁹ bytes convention are the site\'s assumptions for illustration, not numbers from the book; the calculation ignores protocol overhead.</p>'),
      ]),
     (('Tiếp viên điều khiển thông báo, liên lạc nội bộ, IFE và môi trường từ bảng FAP; thông báo luôn ưu tiên hơn IFE, và chuông báo có quy ước âm', 'Cabin crew run announcements, interphone, IFE and environment from the FAP; announcements always outrank IFE and chimes follow a tone convention'),
      [('Bảng tiếp viên, thông báo và liên lạc', 'Attendant panels, announcements and interphone'), ('Chuông báo hiệu 494 Hz và 587 Hz', 'The 494 Hz and 587 Hz chimes')], [
       ('Bảng tiếp viên phía trước điều khiển thông báo, liên lạc nội bộ, cấu hình IFE và môi trường theo năm mức ưu tiên thông báo', 'The forward attendant panel controls announcements, interphone, IFE configuration and the environment, with five announcement priority levels',
        '<p>(Tooley 19.3.1 đến 19.3.4.) <b>FAP</b> thường gần cửa trước bên trái, phức tạp hơn các bảng khác: thông báo cho hành khách, liên lạc nội bộ (interphone), điều khiển dịch vụ IFE, giám sát và điều khiển môi trường. Thông báo phát qua loa trong cabin và tai nghe IFE, với mức ưu tiên lập trình trong dữ liệu cấu hình cabin:</p>' + pa_vi + '<p>Tiếp viên cũng chọn kênh âm thanh và video, video theo yêu cầu (VOD), thông tin chuyến bay và bản đồ động, điện thoại, trò chơi và internet; hành khách luôn tự chỉnh đèn đọc sách và luồng khí cục bộ, còn tiếp viên điều khiển chiếu sáng theo vùng ở mọi giai đoạn bay.</p>',
        '<p>(Tooley 19.3.1 to 19.3.4.) The <b>FAP</b> is usually near the forward left door and more complex than the other panels: passenger announcements, interphone communication, control of IFE services, environmental monitoring and control. Announcements go through cabin loudspeakers and IFE headsets, with priority levels programmed in the cabin configuration data:</p>' + pa_en + '<p>The crew also choose audio and video channels, video on demand (VOD), flight information and moving maps, telephone, games and internet; passengers can always adjust their reading lights and local airflow, while the cabin crew control zone lighting at every stage of flight.</p>',
        '<p>Một interphone dịch vụ cho phép buồng lái, tiếp viên và nhân viên mặt đất liên lạc khi máy bay đỗ, qua ổ cắm ở bảng điện mặt đất. Khi IFE bật, thông báo luôn được ưu tiên.</p>', '<p>A service interphone lets the flight deck, cabin crew and ground crew talk while the aircraft is on the ground, through a jack at the ground electrical panel. While the IFE is on, announcements always take priority.</p>'),
       (f'Chuông cabin là chuỗi sin 900 ms ở 494 Hz (thấp) và 587 Hz (cao), kết hợp thành bốn tín hiệu qua hệ thông báo', f'Cabin chimes are 900 ms sine bursts at 494 Hz (low) and 587 Hz (high), combined into four signals through the PA system',
        '<p>(Tooley 19.3.5.) Báo hiệu tổ bay có nhiều dạng (âm thanh, hình ảnh) để xử lý các tình huống như "sẵn sàng cất cánh/hạ cánh" hay "không làm phiền". Chuông thấp và cao là các chuỗi hình sin tinh khiết 900 ms ở 494 Hz và 587 Hz:</p>' + ch_vi + formula('Số chu kỳ và chu kỳ của chuông', r'N=f\,t=494\times0{,}9\approx445\text{ chu kỳ},\qquad T=\frac1f=2{,}02\text{ ms}\;(494\text{ Hz}),\;1{,}70\text{ ms}\;(587\text{ Hz})'),
        '<p>(Tooley 19.3.5.) Crew alerting has several audible and visual forms to cope with cases such as "ready for take-off/landing" or "do not disturb". The low and high chimes are pure sine bursts of 900 ms at 494 Hz and 587 Hz:</p>' + ch_en + formula('Cycles and period of the chimes', r'N=f\,t=494\times0.9\approx445\text{ cycles},\qquad T=\frac1f=2.02\text{ ms}\;(494\text{ Hz}),\;1.70\text{ ms}\;(587\text{ Hz})'),
        f'<p>Tỉ số 587/494 = {C.ratio(494, 587):.3f}'.replace('.', ',') + ' gần một quãng ba thứ (1,2). Chuông được phát qua hệ PA, và chỉ có ý nghĩa với thành viên tổ bay. Site tính số chu kỳ và chu kỳ bằng hai cách (nhân và chia số hữu tỉ): khớp.</p>', f'<p>The ratio 587/494 = {C.ratio(494, 587):.3f} is close to a minor third (1.2). The chimes are played through the PA system and mean something only to crew members. The site computed the cycle count and period two ways (multiplication and rational division): they agree.</p>'),
     ]),
     (('EFB thay túi tài liệu của phi công bằng thiết bị điện tử, chia loại di động và lắp sẵn, ứng dụng loại A và B; ca G-EZWE cho thấy lỗi dữ liệu có thể gây nguy hiểm', 'The EFB replaces the pilot\'s flight bag with electronics, in portable and installed classes and Type A and B applications; the G-EZWE case shows a data error can be dangerous'),
      [('Hệ thông tin tàu bay và tính toán cất cánh', 'Aircraft information systems and the take-off calculation'), ('EFB: loại thiết bị và loại phần mềm', 'EFB: equipment classes and software types'), ('Ca G-EZWE và hệ thông tin tích hợp', 'The G-EZWE case and integrated information systems')], [
       ('Hệ thông tin gồm người, phần mềm, phần cứng và dữ liệu; tính cất cánh cần V1, VR, V2 và quãng đường sẵn có', 'An information system is people, software, hardware and data; the take-off calculation needs V1, VR, V2 and the available distance',
        '<p>(Tooley 20.1.) Hệ thông tin là hệ máy tính có phần mềm thu thập, lưu và xử lý dữ liệu để cho thông tin và hiểu biết; con người là một phần của hệ. Bốn loại trên tàu bay vận tải: EFB và nhật ký điện tử (ELB), hệ thông tin cabin, hệ thông tin bảo dưỡng và hệ quản lý thông tin và không lưu (ATIMS). Ví dụ giai đoạn cất cánh: quãng đường cất cánh là tổng quãng chạy đà và quãng ngang để bay lên độ cao màn chắn 35 ft; phụ thuộc khối lượng, mật độ không khí, gió, tình trạng đường băng và cấu hình cánh tà.</p>' + table(['Tốc độ', 'Ý nghĩa'], [['V1', 'tốc độ tối đa phi công phải bắt đầu dừng máy bay khi hỏng động cơ tới hạn'], ['VR', 'tốc độ bắt đầu nhấc bánh mũi'], ['VLO', 'tốc độ rời mặt đất'], ['V2', 'tốc độ an toàn tại độ cao màn chắn'], ['VS', 'tốc độ chòng chành']]) + '<p>Ví dụ B737 (79 000 kg, TODA 2,1 km, khô ráo): V1 = 124 kt, VR = 125 kt, V2 = 136 kt.</p>',
        '<p>(Tooley 20.1.) An information system is a computer system with software that collects, stores and processes data to give information and knowledge; people are part of it. Four kinds on a transport aircraft: EFB and electronic logbooks (ELB), cabin information systems, maintenance information systems and air traffic and information management systems (ATIMS). Take-off example: the take-off distance is the ground run plus the horizontal distance to climb to a 35 ft screen height; it depends on weight, air density, wind, runway condition and flap configuration.</p>' + table(['Speed', 'Meaning'], [['V1', 'the maximum speed at which the pilot must begin to stop after a critical engine failure'], ['VR', 'the speed at which the nose gear is raised'], ['VLO', 'the lift-off speed'], ['V2', 'the safety speed at the screen height'], ['VS', 'the stalling speed']]) + '<p>Boeing 737 example (79,000 kg, TODA 2.1 km, dry): V1 = 124 kt, VR = 125 kt, V2 = 136 kt.</p>',
        '<p>Ba tốc độ của ví dụ tăng dần 124 < 125 < 136 kt, đúng thứ tự V1, VR, V2. Số liệu đã kiểm trên ảnh trang 320 của sách.</p>', '<p>The three speeds of the example increase 124 < 125 < 136 kt, in the order V1, VR, V2. The figures were checked on page image 320 of the book.</p>'),
       ('EFB chia thành di động (không cần chứng nhận) và lắp sẵn (thuộc thiết kế kiểu loại); phần mềm loại A không ảnh hưởng an toàn, loại B cần đánh giá', 'EFBs split into portable (no certification) and installed (part of the type design); Type A software has no safety effect, Type B needs assessment',
        '<p>(Tooley 20.2.) EFB thay túi tài liệu của phi công: tài liệu điện tử, tính hiệu năng, hải đồ và bản đồ, nhận biết vị trí trên đường lăn, giám sát video, liên kết với hệ thống của hãng. EFB không được thay thiết bị lắp sẵn bắt buộc. Trước 2017 có Class 1 (COTS không lắp sẵn), Class 2 (COTS cải tiến, có thể cần chứng nhận bổ sung), Class 3 (lắp sẵn, chịu yêu cầu đủ điều kiện bay); nay chỉ còn hai loại:</p>' + table(['', 'EFB di động', 'EFB lắp sẵn'], [['Thuộc thiết kế kiểu loại', 'không', 'có'], ['Chứng nhận', 'không cần', 'cần'], ['Phần cứng', 'máy tính bảng, laptop (pin hoặc nguồn tàu bay); là PED', 'hai bộ hiển thị DU nối với EU ở khoang điện tử (B777: hai máy tính, Linux và Windows)'], ['Phần mềm', 'loại A hoặc B', 'có thể cả ứng dụng quan trọng hơn']]) + table(['Loại phần mềm', 'Ví dụ', 'Hệ quả an toàn'], [['Type A', 'trình đọc PDF, XML, HTML: sổ tay, tài liệu', 'không có'], ['Type B', 'khối lượng và cân bằng, hiệu năng, bản đồ động', 'không làm tổn hại an toàn; nhà khai thác phải đánh giá']]),
        '<p>(Tooley 20.2.) The EFB replaces the pilot\'s flight bag: electronic documents, performance calculation, charts and maps, taxiway position awareness, video surveillance and links to company systems. An EFB must not replace required installed equipment. Before 2017 there were Class 1 (non-installed COTS), Class 2 (modified COTS, possibly needing a supplemental certificate) and Class 3 (installed, subject to airworthiness requirements); now there are two classes:</p>' + table(['', 'Portable EFB', 'Installed EFB'], [['Part of the type design', 'no', 'yes'], ['Certification', 'not needed', 'needed'], ['Hardware', 'tablet, laptop (battery or aircraft power); a PED', 'two display units DU linked to EUs in the avionics bay (B777: two computers, Linux and Windows)'], ['Software', 'Type A or B', 'may include more critical applications']]) + table(['Software type', 'Examples', 'Safety consequence'], [['Type A', 'PDF, XML, HTML readers: manuals, documents', 'none'], ['Type B', 'mass and balance, performance, moving maps', 'must not compromise safety; the operator must assess']]),
        '<p>Ứng dụng điều khiển chủ động tàu bay hoặc sao chép hệ avionics đã chứng nhận không phải ứng dụng EFB và phải được phê chuẩn đủ điều kiện bay đầy đủ (Chương 20 câu 3).</p>', '<p>An application that actively controls the aircraft or duplicates a certified avionics system is not an EFB application and needs full airworthiness approval (Chapter 20 Q3).</p>'),
       ('Ca G-EZWE: dùng quãng đường băng sai trong EFB khiến máy bay rời mặt đất khi chỉ còn 110 m; hệ thông tin tích hợp tách "thế giới avionics" khỏi "thế giới mở" bằng tường lửa', 'G-EZWE: the wrong runway length in the EFB made the aircraft lift off with only 110 m left; an integrated information system separates the "avionics world" from the "open world" with a firewall',
        '<p>(Tooley 20.1.1, 20.2.5, 20.3.) Tháng 9 năm 2019 một Airbus A320-214 (G-EZWE) gặp sự cố nghiêm trọng ở Lisbon. AAIB kết luận do dùng dữ liệu sai khi tính hiệu năng cất cánh: tổ lái tin rằng đã chọn đường băng ngắn nhất nhưng đã dùng chiều dài đầy đủ, trong khi cất cánh từ một giao lộ đường lăn; quãng sẵn có ngắn hơn 1 395 m so với quãng dùng để tính, máy bay rời mặt đất khi chỉ còn 110 m đường băng. Ứng dụng tính nằm trong EFB. Bài học: kiểm tra tính hợp lệ dữ liệu EFB, đối chiếu tính toán trước khi nhập vào máy tính quản lý bay, giảm xao nhãng; nhà khai thác đổi sang phiên bản có hình đường băng. Ngày đó giá đỡ EFB của cơ trưởng đã hỏng và pin yếu. <b>Hệ thông tin tích hợp</b> (20.3): máy chủ mạng (NSS) chạy các ứng dụng thông tin trên tàu cho ba miền (avionics, khai thác bay, truyền thông/cabin) với bốn loại giao diện người dùng; Boeing AIMS là hệ dựa trên IMA.</p>',
        '<p>(Tooley 20.1.1, 20.2.5, 20.3.) In September 2019 an Airbus A320-214 (G-EZWE) had a serious incident at Lisbon. The AAIB attributed it to incorrect data in the take-off performance calculation: the crew believed they had selected the shortest runway length but used the full length while taking off from a taxiway intersection; the distance available was 1,395 m less than used and the aircraft lifted off with only 110 m of runway left. The calculation application was in the EFB. Lessons: validate EFB data, cross-check calculations before entering them in the flight management computer, reduce distractions; the operator moved to a version with a picture of the runway. That day the captain\'s EFB cradle was broken and the battery was weak. In an <b>integrated information system</b> (20.3) a network server (NSS) hosts on-board information applications for three domains (avionics, flight operations, communication/cabin) with four kinds of user interface; Boeing\'s AIMS is IMA-based.</p>',
        '<p>Đây là ví dụ về hệ quả của lỗi nhập dữ liệu trong hệ thông tin: phần mềm đúng nhưng dữ liệu đầu vào sai vẫn nguy hiểm. Chi tiết số (1 395 m, 110 m) lấy nguyên văn từ sách.</p>', '<p>This shows the consequence of a data-entry error in an information system: correct software with wrong input data is still dangerous. The figures (1,395 m, 110 m) are quoted from the book.</p>'),
     ]),
    ]
    exs = [
      (('Ví dụ 1: số chu kỳ của chuông cao', 'Example 1: cycles in the high chime'), ('587 Hz kéo dài 900 ms: $587\\times0{,}9=528{,}3$ chu kỳ ≈ 528.', '587 Hz lasting 900 ms: $587\\times0.9=528.3$ cycles ≈ 528.'), f'{C.cycles(587, 0.9):.1f}'),
      (('Ví dụ 2: chu kỳ của chuông thấp', 'Example 2: period of the low chime'), ('$T=1/494=2{,}024$ ms.', '$T=1/494=2.024$ ms.'), f'{C.period(494) * 1e3:.3f} ms'),
      (('Ví dụ 3: nạp phim 4,7 GB qua 100 Mbit/s', 'Example 3: loading a 4.7 GB film over 100 Mbit/s'), ('$t=4{,}7\\times8\\times10^9/10^8=376$ s ≈ 6,3 phút (giả định của site).', '$t=4.7\\times8\\times10^9/10^8=376$ s ≈ 6.3 min (the site\'s assumption).'), f'{C.load_time(4.7, 100e6):.0f} s'),
      (('Ví dụ 4: nạp cùng phim qua 1 Gbit/s', 'Example 4: the same film over 1 Gbit/s'), ('Nhanh gấp 10 lần: 37,6 s.', 'Ten times faster: 37.6 s.'), f'{C.load_time(4.7, 1e9):.1f} s'),
      (('Ví dụ 5: thứ tự tốc độ B737', 'Example 5: order of the B737 speeds'), ('V1 = 124 kt < VR = 125 kt < V2 = 136 kt.', 'V1 = 124 kt < VR = 125 kt < V2 = 136 kt.'), '124 < 125 < 136'),
    ]
    return build(parts, exs,
        ('Các hệ thống phục vụ hành khách và thông tin trên tàu bay hiện đại: máy chủ mạng cabin (ARINC 628), giải trí IFE, thông báo, liên lạc và chuông gọi, rồi cặp tài liệu điện tử EFB, hệ thông tin tích hợp và bài học từ ca G-EZWE. Dựng từ Tooley Chương 19 và 20 (không có slide của giảng viên).',
         'The systems that serve passengers and information on a modern aircraft: the cabin network server (ARINC 628), IFE, announcements, interphone and chimes, then the electronic flight bag (EFB), integrated information systems and the lessons of the G-EZWE case. Built from Tooley Chapters 19 and 20 (no lecturer slides).'),
        [('liệt kê các phân hệ cabin và bốn loại người dùng của CNSS, và nêu vai trò của ARINC 628', 'list the cabin subsystems and the four kinds of CNSS user, and state the role of ARINC 628'), ('mô tả head-end, phân phối và phân hệ ghế của IFE và tính thời gian nạp phương tiện', 'describe the IFE head-end, distribution and seat subsystems and compute the media loading time'),
         ('nêu thứ tự ưu tiên thông báo và quy ước chuông cabin', 'state the announcement priority order and the cabin chime convention'), ('phân biệt EFB di động với lắp sẵn và ứng dụng loại A với B', 'tell portable from installed EFB and Type A from Type B applications'), ('giải thích hệ quả dữ liệu sai trong ca G-EZWE và vai trò của V1, VR, V2', 'explain the consequence of wrong data in the G-EZWE case and the roles of V1, VR, V2')],
        ('Module không có slide của giảng viên. Tooley Chương 19 (tr.307 đến 316, PDF tr.321 đến 330) và Chương 20 (tr.317 đến 335, PDF tr.331 đến 349). Câu hỏi gốc: 7 câu Chương 19 (khoá A.19, tr.382) và 9 trong 10 câu Chương 20 (khoá A.20, tr.382 đến 383; câu 10 cần Hình 20.11 chưa đưa vào). Floyd không có phần tương ứng. Tooley Chương 12 (ESD, tr.197 đến 206) được gắn vào Module 09.',
         'The module has no lecturer slides. Tooley Chapter 19 (pp.307 to 316, PDF pp.321 to 330) and Chapter 20 (pp.317 to 335, PDF pp.331 to 349). Original questions: 7 of Chapter 19 (key A.19, p.382) and 9 of the 10 in Chapter 20 (key A.20, pp.382 to 383; Q10 needs Figure 20.11 and is not in yet). Floyd has no matching part. Tooley Chapter 12 (ESD, pp.197 to 206) is attached to Module 09.'),
        [('Tooley Chương 20 câu 10 (chức năng của khối X trong Hình 20.11) chưa được đưa vào ngân hàng vì cần ảnh hình; khoá in là (b) liên kết chéo hệ điều hành, nhất quán với văn bản 20.2.7 nhưng chưa kiểm trên hình. Đây là việc CHƯA LÀM.', 'Tooley Chapter 20 Q10 (the function of block X in Figure 20.11) is not in the bank because it needs the figure; the printed key is (b) operating system cross-link, consistent with the text of 20.2.7 but not checked on the figure. This is NOT DONE.'),
         ('Số liệu "kích thước phim 4,7 GB" và quy ước 1 GB = 10⁹ byte trong phần tính thời gian nạp phương tiện là giả định minh hoạ của site, không phải số của sách (sách chỉ nói 100 Mbps có thể đủ nhưng Gigabit Ethernet được ưu tiên).', 'The "4.7 GB film" and the 1 GB = 10⁹ bytes convention in the media-loading calculation are the site\'s illustrative assumptions, not numbers of the book (the book only says 100 Mbps may suffice but Gigabit Ethernet is preferred).'),
         ('Chi tiết ca G-EZWE (1 395 m, 110 m, tháng 9 năm 2019, EasyJet) lấy nguyên văn từ Tooley 20.1.1; site không đối chiếu với báo cáo AAIB gốc.', 'The G-EZWE details (1,395 m, 110 m, September 2019, EasyJet) are quoted from Tooley 20.1.1; the site did not check them against the original AAIB report.')])
